local RegressionNewGiftBagPanel = Class('RegressionNewGiftBagPanel')
---@type RegressionUtils
local RegressionUtils = import('Game.Activity.RegressionActivity.RegressionUtils')
local GiftCount = 6
local GiftCellPath = "Game.Activity.RegressionActivity.Cell.RegressionNewGiftBagCell"

function RegressionNewGiftBagPanel:__init()
	self.giftEnv = {}
end

function RegressionNewGiftBagPanel:__delete()
	self.giftEnv = nil
end

function RegressionNewGiftBagPanel:Awake()
	self:InitGiftEnv()
end

function RegressionNewGiftBagPanel:InitGiftEnv()
	for i = 1, GiftCount do
		local giftNode = self["RegressionNewGiftBagNode"..i]
		if isNotNull(giftNode) then
			local env = CfUtils.GetLuaScr(giftNode, GiftCellPath)
			if env then
				self.giftEnv[i] = env
			end
		end
	end
end

function RegressionNewGiftBagPanel:RefreshTopGoods()
	CfUtils.RefreshTopGoods({Constants.Currency.PayDiamondId, Constants.Currency.FreeDiamondId})
end

function RegressionNewGiftBagPanel:Refresh(config)
	self.config = config
	self.dojo = RegressionUtils.GetRegressHomeDojo()
	self.data = self.dojo:GetGiftInfo()
	for i = 1, GiftCount do
		local giftData = self.data.products[i]
		CfUtils.SetActive(self.giftEnv[i].controller.gameObject, isNotNull(giftData))
		if isNotNull(giftData) then
			self.giftEnv[i]:RefreshCell(giftData, self.config.type)
		end
	end
end

function RegressionNewGiftBagPanel:OnDestroy()
	self.controller = nil--luabehaviour 中CSharp对象
	self:Delete()
end

return RegressionNewGiftBagPanel